from solution import extract_freq


def test_issue_example_given():
    """Example [(3,4),(1,2),(4,3),(5,6)] has 3 unique tuples order irrespective."""
    assert extract_freq([(3, 4), (1, 2), (4, 3), (5, 6)]) == 3  # 4-1=3


def test_issue_empty_list():
    """Empty list has frequency 0 of unique tuples."""
    assert extract_freq([]) == 0  # 0+0=0


def test_issue_single_tuple():
    """Single tuple has frequency 1 order irrespective."""
    assert extract_freq([(1, 2)]) == 1  # 0+1=1


def test_issue_exact_duplicates():
    """Exact duplicate tuples count as one unique tuple."""
    assert extract_freq([(1, 2), (1, 2), (1, 2)]) == 1  # 3-2=1


def test_issue_reversed_pair():
    """Reversed pair (3,4) and (4,3) counts as one unique tuple order irrespective."""
    assert extract_freq([(3, 4), (4, 3)]) == 1  # 2-1=1


def test_issue_all_unique_pairs():
    """Three distinct pairs have frequency 3 order irrespective."""
    assert extract_freq([(1, 2), (3, 4), (5, 6)]) == 3  # 3+0=3


def test_issue_mixed_exact_and_reversed():
    """Mix of exact and reversed duplicates has 2 unique tuples."""
    assert extract_freq([(1, 2), (2, 1), (1, 2), (3, 4)]) == 2  # 4-2=2


def test_issue_three_element_permutation():
    """Permuted 3-tuples count as one unique tuple order irrespective."""
    assert extract_freq([(1, 2, 3), (3, 2, 1), (4, 5, 6)]) == 2  # 3-1=2


def test_contract_returns_integer_count():
    """Frequency is returned as an integer count."""
    assert extract_freq([(7, 8), (8, 7)]) == 1  # 2-1=1


def test_contract_list_order_independent():
    """Unique count does not depend on input list order."""
    assert extract_freq([(1, 2), (3, 4), (2, 1)]) == extract_freq([(2, 1), (3, 4), (1, 2)]) == 2  # 3-1=2
